}

fn reject_scripts_and_discovery(
    manifest: &JsonMap<String, JsonValue>,
    dependency: bool,
) -> Result<()> {
    if manifest.contains_key("scripts") {
        bail!("npm vendored lifecycle scripts are unsupported");
    }
    let mut fields = vec![
        "devDependencies",
        "optionalDependencies",
        "peerDependencies",
        "overrides",
        "workspaces",
        "bundledDependencies",
        "bundleDependencies",
    ];
    if dependency {
        fields.push("dependencies");
    }
    if fields.iter().any(|field| manifest.contains_key(*field)) {
        bail!("npm vendored dependency discovery is unsupported");
    }
    Ok(())
}

fn identity(value: &JsonMap<String, JsonValue>, name: &str, version: &str) -> Result<()> {
    require_text(value, "name", name)?;
    require_text(value, "version", version)
}

fn require_text(value: &JsonMap<String, JsonValue>, field: &str, expected: &str) -> Result<()> {
    if value.get(field).and_then(JsonValue::as_str) != Some(expected) {
        bail!("npm vendored {field} differs from its explicit input");
    }
    Ok(())
}

